const sha=(value)=>createHash('sha256').update(value).digest('hex');
const posix=(value)=>value.replaceAll('\\','/');
const fileHash=(file)=>fs.existsSync(file)?sha(fs.readFileSync(file)):null;
function dataUri(filename){const file=path.join(assetRoot,filename);if(!fs.existsSync(file))return '';const mime=filename.toLowerCase().endsWith('.png')?'image/png':'image/webp';return `data:${mime};base64,${fs.readFileSync(file).toString('base64')}`;}
function writeJson(file,value){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,`${JSON.stringify(value,null,2)}\n`,'utf8');}

function field(label,value='',attrs=''){return `<label class="field">${label}<input data-interactive="true" ${attrs} value="${esc(value)}"></label>`;}
